2. Add `src/stories/InjectorTeardown.stories.ts` to the sandbox:

   ```ts
   import { ApplicationRef, Component, EnvironmentInjector, inject } from '@angular/core';
   import type { Meta, StoryObj } from '@storybook/angular';

   @Component({ selector: 'injector-teardown', template: 'first story' })
   class InjectorTeardownComponent {
     private injector = inject(EnvironmentInjector);

     ngOnDestroy() {
       // Mirrors a teardown path that reads from the injector,
       // for example CDK overlay removal with animate.leave.
       this.injector.get(ApplicationRef);
     }
   }

   export default {
     title: 'Bug/InjectorTeardown',
     component: InjectorTeardownComponent,
   } satisfies Meta<InjectorTeardownComponent>;

   export const First: StoryObj<InjectorTeardownComponent> = {};

   export const Second: StoryObj = {
     render: () => ({ template: 'second story' }),
   };
   ```

